SELECT CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 100 THEN 'mid' ELSE 'low' END AS unit_price_bucket, AVG(unit_price) AS avg_unit_price FROM order_items GROUP BY CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 100 THEN 'mid' ELSE 'low' END ORDER BY avg_unit_price DESC, unit_price_bucket
